import math

def _final(r):
    return r.get("final_state") or {}

def _init_z(r, name):
    o = (_final(r).get("objects") or {}).get(name) or {}
    ip = o.get("init_pos")
    return float(ip[2]) if ip else None

def _final_z(r, name):
    o = (_final(r).get("objects") or {}).get(name) or {}
    p = o.get("pos")
    return float(p[2]) if p else None

def _final_xy(r, name):
    o = (_final(r).get("objects") or {}).get(name) or {}
    p = o.get("pos")
    return (float(p[0]), float(p[1])) if p else None

def _maxz(r, name):
    # max z the object reached: over trace points and the final pos
    zmax = None
    pts = (r.get("trace") or {}).get("points") or []
    for p in pts:
        o = ((p.get("objects") or {}).get(name) or {})
        pos = o.get("pos")
        if pos is not None:
            try:
                z = float(pos[2])
                if zmax is None or z > zmax: zmax = z
            except Exception:
                pass
    fz = _final_z(r, name)
    if fz is not None and (zmax is None or fz > zmax):
        zmax = fz
    return zmax

def _shaped(r):
    try:
        return float(r.get("reward") or 0.0)
    except Exception:
        return 0.0

def _lifted(r, name, thresh=0.04):
    iz = _init_z(r, name)
    mz = _maxz(r, name)
    if mz is None or iz is None:
        return False
    return (mz - iz) > thresh

def _aligned(r, above, base):
    az = _final_z(r, above); bz = _final_z(r, base)
    axy = _final_xy(r, above); bxy = _final_xy(r, base)
    if None in (az, bz, axy, bxy):
        return False
    dz = az - bz
    dxy = math.hypot(axy[0]-bxy[0], axy[1]-bxy[1])
    return (dz > 0.02) and (dxy < 0.06)

def reward(r):
    if r.get("task_completed"):
        return 1.0
    task = r.get("task", "")
    sh = _shaped(r)
    if task == "restack":
        # suppress the cheap "shove the green off the red" component
        stages = r.get("stages") or {}
