        return min(1.0, 0.25 * sh + 0.5 * lifted + 0.25 * aligned)
    if task == "revstack":
        lifted = 1.0 if _lifted(r, "green_cube") else 0.0
        aligned = 1.0 if _aligned(r, "green_cube", "red_cube") else 0.0
        return min(1.0, 0.25 * sh + 0.5 * lifted + 0.25 * aligned)
